const getRecommendations = async (userId) => {
  return User.aggregate([
    { $match: { _id: mongoose.Types.ObjectId(userId) } },
    {
      $lookup: {
        from: "songs",
        localField: "recommendedTracks",
        foreignField: "_id",
        as: "trackDetails"
      }
    },
    { $unwind: "$trackDetails" },
    {
      $project: {
        _id: 0,
        trackId: "$trackDetails._id",
        title: "$trackDetails.title"
      }
    }
  ]);
};
